/* Editor layout and frame atmosphere controls. */
(function(){'use strict';let section='all';const heading=$('.inspector .panelheading');heading.innerHTML='<strong>Properties</strong><button id="collapseRight" title="Collapse properties" aria-label="Collapse properties">›</button>';
$('.library .panelheading').innerHTML='<strong>Library</strong><button id="collapseLeft" title="Collapse library" aria-label="Collapse library">‹</button>';
const bar=document.createElement('div');bar.className='property-tabs';bar.innerHTML=['all','object','frame','camera','effects'].map(k=>`<button data-property-tab="${k}" class="${k==='all'?'active':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('');heading.parentNode.insertBefore(bar,$('#inspectorContent'));
const restore=document.createElement('div');restore.className='workspace-controls';restore.innerHTML='<button id="focusCanvas" title="Expand canvas, keeping playback visible">⛶ Focus</button><button id="showLibrary" title="Toggle library">Library</button><button id="showProperties" title="Toggle properties">Properties</button><label>Canvas <input id="workspaceZoom" aria-label="Canvas workspace zoom" type="range" min="50" max="300" value="100" step="10"></label><label>Timeline <input id="timelineSize" aria-label="Timeline height" type="range" min="140" max="420" value="170" step="10"></label>';$('.stagehead').parentNode.insertBefore(restore,$('.stagearea'));
let focusPrevious=null;$('#focusCanvas').onclick=()=>{const w=$('.workspace');if(!focusPrevious){focusPrevious={left:w.classList.contains('left-collapsed'),right:w.classList.contains('right-collapsed')};w.classList.add('left-collapsed','right-collapsed','canvas-focused');$('#focusCanvas').textContent='↙ Restore'}else{w.classList.toggle('left-collapsed',focusPrevious.left);w.classList.toggle('right-collapsed',focusPrevious.right);w.classList.remove('canvas-focused');focusPrevious=null;$('#focusCanvas').textContent='⛶ Focus'}window.WorkspaceView?.resize()};function toggle(side){$('.workspace').classList.toggle(side+'-collapsed');window.WorkspaceView?.resize()}
$('#collapseLeft').onclick=$('#showLibrary').onclick=()=>toggle('left');$('#collapseRight').onclick=$('#showProperties').onclick=()=>toggle('right');$('#workspaceZoom').oninput=()=>zoomViewport(Number($('#workspaceZoom').value)/100);$('#timelineSize').oninput=()=>{$('.timeline').style.height=$('#timelineSize').value+'px';window.WorkspaceView?.resize()};
function filter(){for(const el of $('#inspectorContent').children){if(el.tagName!=='SECTION')continue;const title=el.querySelector('h3')?.textContent||'';let category=title==='Scene effects'?'effects':title==='Visual effects'||title==='Object animation'?'effects':el.id==='camera-panel'||title==='Camera'?'camera':/^Frame \d/.test(title)||title==='Audio track'||title==='Scene'?'frame':'object';el.hidden=section!=='all'&&category!==section;}$$('[data-property-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.propertyTab===section);b.setAttribute('aria-pressed',String(b.dataset.propertyTab===section))})}
$$('[data-property-tab]').forEach(b=>b.onclick=()=>{section=b.dataset.propertyTab;filter()});
const previous=renderInspector;renderInspector=function(){previous();const fx=frame().sceneEffects||{},host=$('#inspectorContent');host.insertAdjacentHTML('beforeend',`<section><h3>Scene effects</h3><p class="note">Weather and atmosphere across this frame. No object needed.</p><div class="scene-effect-grid">${M.weather.types.map(k=>`<label><input type="checkbox" data-weather="${k}" ${fx.types?.includes(k)?'checked':''}>${k.replaceAll('-',' ')}</label>`).join('')}</div>${[['intensity','Density / intensity',0,1,.05,.6],['speed','Speed',.1,3,.1,1],['direction','Wind direction',-1,1,.1,.3]].map(([key,label,min,max,step,v])=>`<label class="field">${label}<input type="range" data-weather-setting="${key}" min="${min}" max="${max}" step="${step}" value="${fx[key]??v}"></label>`).join('')}<div class="row"><button id="previewWeather">▶ Preview frame</button><button id="clearWeather">Clear effects</button></div></section>`);$$('[data-weather]').forEach(b=>b.onchange=()=>{remember();const f=frame();f.sceneEffects??={types:[]};const set=new Set(f.sceneEffects.types);b.checked?set.add(b.dataset.weather):set.delete(b.dataset.weather);f.sceneEffects.types=[...set];changed()});$$('[data-weather-setting]').forEach(b=>b.onchange=()=>{remember();frame().sceneEffects??={types:[]};frame().sceneEffects[b.dataset.weatherSetting]=Number(b.value);changed()});$('#clearWeather').onclick=()=>{remember();delete frame().sceneEffects;changed()};$('#previewWeather').onclick=()=>{AudioTimeline.seek(startTime());play()};filter()};
const validate=validateProject;validateProject=p=>{p=validate(p);for(const f of [...p.frames,...Object.values(p.customPlaces||{})])if(f.sceneEffects){const fx=f.sceneEffects;if(!Array.isArray(fx.types))throw Error('Invalid scene effects.');fx.types=[...new Set(fx.types.filter(k=>M.weather.types.includes(k)))];for(const [key,min,max,def] of [['intensity',0,1,.6],['speed',.1,3,1],['direction',-1,1,.3]])fx[key]=Number.isFinite(fx[key])?Math.max(min,Math.min(max,fx[key])):def;}return p};renderInspector();window.WorkspaceUI={filter};})();
